/**
 * A stand-in for Forma, for building themes in a plain browser.
 *
 * It answers from `library.json`: the real engine's output for the repository's fixture
 * library, regenerated by `cargo run -p forma-core --example mock_snapshot`. What a theme sees
 * here is what Forma would send. Favourites, settings and play stats change in memory;
 * views are a snapshot, so a new favourite does not move into the Favourites view.
 */
import type { Backend } from '../backend.js';
import { type ErrorCode, FormaError } from '../errors.js';
import type {
  BluetoothDevice,
  Browse,
  Collection,
  RaSession,
  RoomFilter,
  BatoceraSetting,
  OptionItem,
  OptionsPage,
  OptionsScope,
  InfoItem,
  SystemSetting,
  StorePackage,
  DefaultView,
  EthernetConfig,
  Game,
  GameEnd,
  GameStart,
  LibraryChanged,
  MusicSource,
  MusicStatus,
  NetplayRoom,
  NetworkStatus,
  Radio,
  RaGame,
  RaUser,
  SystemSummary,
  ThemeInfo,
  CatalogueTheme,
  Fetched,
  Magazine,
  ThemeCatalogue,
  Unsubscribe,
  ViewInfo,
  WifiNetwork
} from '../types.js';
import data from './library.json' with { type: 'json' };

export interface MockOptions {
  /** How long a mock game "plays" before `game:end`. */
  playMs?: number;
  /** Permissions the mock pretends the theme declared, e.g. `settings.system`. */
  permissions?: string[];
  /** Pretend RetroAchievements is set up (default) or not. */
  ra?: boolean;
}

interface Snapshot {
  apiVersion: string;
  systems: SystemSummary[];
  views: ViewInfo[];
  games: Game[];
  browse: Record<string, Browse>;
  ra: { user: RaUser; games: Record<string, RaGame> };
  lobby: NetplayRoom[];
  network: { status: NetworkStatus; wifi: WifiNetwork[] };
  batocera: BatoceraSetting[];
  music: { sources: MusicSource[]; radios: Radio[] };
  /** The engine's option pages: `global`, and `system|emulator|core` (empty: not set). */
  options: Record<string, OptionsPage>;
  system: { info: InfoItem[]; settings: SystemSetting[] };
  store: StorePackage[];
}

const snapshot = data as unknown as Snapshot;
/** How many pages each mock magazine has. */
const MAGAZINE_PAGES = 8;

type Handler = (payload: unknown) => void;

function fail(code: ErrorCode, message: string): never {
  throw new FormaError(code, message);
}

/** Lower-case without accents, for search the way SQLite's FTS does it. */
function fold(s: string): string {
  return s
    .normalize('NFD')
    .replace(/\p{Diacritic}/gu, '')
    .toLowerCase();
}

export function mockBackend(options: MockOptions = {}): Backend {
  const playMs = options.playMs ?? 1500;
  const permissions = new Set(options.permissions ?? []);
  // A second, installed theme, so a theme manager has something to show and remove.
  const extraThemes: ThemeInfo[] = [
    {
      id: 'neon',
      name: 'Neon',
      version: '1.2.0',
      origin: 'user',
      author: 'RAM Raiders',
      description: 'Bright lines on black.',
      permissions: ['system.power'],
      permissionDescriptions: ['quit Forma, restart or shut down the machine'],
      removable: true,
      update: '1.3.0',
      current: false,
      unavailable: null,
      logo: null
    }
  ];
  // Two magazines of drawn pages, so a reader has something to turn.
  const reading = new Map<string, number>();
  const magazines: Omit<Magazine, 'page'>[] = [
    ['Retro Gamer 1.pdf', 'Retro Gamer 1', '', 'pdf'],
    ['Edge/Edge 9.cbz', 'Edge 9', 'Edge', 'zip']
  ].map(([id, title, folder, format]) => ({
    id: id!,
    title: title!,
    folder: folder!,
    format: format as Magazine['format'],
    pageUrl: `data:image/svg+xml,${encodeURIComponent(
      `<svg xmlns="http://www.w3.org/2000/svg" width="700" height="990"><rect width="100%" height="100%" fill="#f4efe1"/><text x="50%" y="45%" font-size="64" text-anchor="middle">${title}</text><text x="50%" y="55%" font-size="48" text-anchor="middle">page {page}</text></svg>`
    ).replace('%7Bpage%7D', '{page}')}#`
  }));
  // The theme catalogue: a newer Neon, and a theme not installed yet.
  const catalogue: CatalogueTheme[] = [
    {
      id: 'neon',
      name: 'Neon',
      version: '1.3.0',
      author: 'RAM Raiders',
      description: 'Bright lines on black.',
      permissions: ['system.power'],
      permissionDescriptions: ['quit Forma, restart or shut down the machine'],
      previews: [],
      installed: '1.2.0',
      update: true,
      runsHere: true
    },
    {
      id: 'paper',
      name: 'Paper',
      version: '0.4.0',
      author: 'A theme author',
      description: 'Quiet, light and printed.',
      permissions: [],
      permissionDescriptions: [],
      previews: [],
      installed: null,
      update: false,
      runsHere: true
    }
  ];
  const games = new Map<number, Game>(snapshot.games.map((g) => [g.id, structuredClone(g)]));
  const settings = new Map<string, unknown>();
  const listeners = new Map<string, Set<Handler>>();
  let defaultView: string | null = null;
  let shellContext: unknown = null;
  const network = structuredClone(snapshot.network);
  const radios = structuredClone(snapshot.music.radios);
  const musicSources = (): MusicSource[] => [
    ...snapshot.music.sources.filter((s) => s.kind !== 'radio'),
    ...radios.map((r) => ({
      id: `radio:${r.url}`,
      kind: 'radio' as const,
      name: r.name,
      tracks: 0
    }))
  ];
  let music: MusicStatus = {
    state: 'stopped',
    source: null,
    title: null,
    artist: null,
    album: null,
    position: null,
    duration: null,
    track: null,
    tracks: null,
    volume: 60,
    shuffle: false
  };
  /** Changes the mock player, and tells listeners, as Forma does. */
  const playerSet = (change: Partial<MusicStatus>): MusicStatus => {
    const before = music;
    music = { ...music, ...change };
    emit('music:changed', structuredClone(music));
    // A new song, announced as Forma does: not a resume, and not when shown for 0 s.
    const seconds = Number(settings.get('music.songSeconds') ?? 8);
    const isNew =
      music.state === 'playing' &&
      music.title !== null &&
      (music.title !== before.title || music.track !== before.track || before.state === 'stopped');
    if (isNew && seconds > 0) {
      emit('music:song', { title: music.title, artist: music.artist, seconds });
    }
    return structuredClone(music);
  };
  const trackTitle = (n: number) => `Track ${n}`;
  const batocera = new Map(snapshot.batocera.map((s) => [s.key, structuredClone(s)]));
  let playing = false;
  const systemSettings = structuredClone(snapshot.system.settings);
  const store = structuredClone(snapshot.store);
  const updates = { current: '43.1', latest: '44', channel: 'stable' };
  /** Two pads paired, one of them on. */
  const bluetooth: { enabled: boolean; devices: BluetoothDevice[] } = {
    enabled: true,
    devices: [
      {
        address: '00:06:F5:13:C3:50',
        name: 'PLAYSTATION(R)3 Controller',
        controller: true,
        connected: false
      },
      { address: '58:2F:40:8A:11:20', name: '8BitDo Pro 2', controller: true, connected: true }
    ]
  };
  let storeBusy = false;
  /** One store operation at a time, as pacman's lock makes it. */
  const storeWork = async (work: () => Promise<void> | void): Promise<null> => {
    storeAllowed();
    if (storeBusy) fail('unsupported', 'the content downloader is busy with another package');
    storeBusy = true;
    try {
      await work();
    } finally {
      storeBusy = false;
    }
    return null;
  };
  const storePackage = (name: unknown): StorePackage =>
    store.find((p) => p.name === name) ??
    fail('invalid', `\`${String(name)}\` is not a package name`);
  /** The mock's `batocera.conf`, for emulator options. */
  const conf = new Map<string, string>();
  /** A level's key prefix, then each level it inherits from, as Batocera reads them. */
  const levels = (scope: OptionsScope): { prefix: string; from: 'global' | 'system' }[] => {
    if (scope.level === 'global') return [{ prefix: 'global', from: 'global' }];
    const system =
      scope.level === 'system'
        ? scope.system
        : (games.get(scope.game) ?? fail('notFound', `no game ${scope.game}`)).system;
    const own =
      scope.level === 'game'
        ? [
            {
              prefix: `${system}["${games.get(scope.game)!.path.split('/').pop()!}"]`,
              from: 'system' as const
            }
          ]
        : [];
    return [...own, { prefix: system, from: 'system' }, { prefix: 'global', from: 'global' }];
  };
  const optionsPage = (scope: OptionsScope): OptionsPage => {
    const chain = levels(scope);
    let page: OptionsPage | undefined;
    if (scope.level === 'global') page = snapshot.options.global;
    else {
      const system = chain[chain.length - 2]!.prefix;
      // The emulator and core in effect, set at this level or its system's.
      const chosen = (key: string) =>
        chain
          .slice(0, -1)
          .map((l) => conf.get(`${l.prefix}.${key}`))
          .find(Boolean) ?? '';
      // No emulator set: the system's default one, with whatever core is.
      const base = snapshot.options[`${system}||`];
      const emulator =
        chosen('emulator') || (base?.options.find((o) => o.key === 'emulator')?.default ?? '');
      page =
        snapshot.options[`${system}|${emulator}|${chosen('core')}`] ??
        snapshot.options[`${system}|${emulator}|`] ??
        base;
    }
    const fill = (o: OptionItem): OptionItem => {
      const values = chain.map((l) => conf.get(`${l.prefix}.${o.key}`));
      const at = values.slice(1).findIndex(Boolean);
      const parent = at < 0 ? null : { value: values[at + 1]!, from: chain[at + 1]!.from };
      return {
        ...structuredClone(o),
        value: values[0] ?? null,
        // A global emulator or core means nothing to one system.
        inherited:
          parent && (parent.from === 'system' || !['emulator', 'core'].includes(o.key))
            ? parent
            : null
      };
    };
    const found = page ?? fail('notFound', `no system \`${chain[chain.length - 2]?.prefix}\``);
    return { options: found.options.map(fill), flags: [...found.flags] };
  };

  const emit = (event: string, payload: unknown) => {
    for (const handler of listeners.get(event) ?? []) handler(payload);
  };

  const mediaUrl = (gameId: number, kind: string): string =>
    kind === 'video' ? '' : placeholder(games.get(gameId)?.name ?? `Game ${gameId}`, kind);

  /** A labelled placeholder image, so a theme's layout can be judged without real media. */
  function placeholder(name: string, kind: string): string {
    const svg =
      `<svg xmlns="http://www.w3.org/2000/svg" width="400" height="300">` +
      `<rect width="100%" height="100%" fill="#2a2d3a"/>` +
      `<text x="50%" y="50%" fill="#e8e9ee" font-family="sans-serif" font-size="22" ` +
      `text-anchor="middle">${escapeXml(name)}</text>` +
      `<text x="50%" y="62%" fill="#8a8d99" font-family="sans-serif" font-size="14" ` +
      `text-anchor="middle">${escapeXml(kind)}</text></svg>`;
    return `data:image/svg+xml;charset=utf-8,${encodeURIComponent(svg)}`;
  }

  /** The live copy of a game, with media as URLs, as the app sends it. */
  const present = (game: Game): Game => {
    const live = games.get(game.id) ?? game;
    const media: Game['media'] = {};
    for (const kind of Object.keys(live.media) as (keyof Game['media'])[]) {
      const url = mediaUrl(live.id, kind);
      if (url) media[kind] = url;
    }
    return { ...live, media };
  };

  /** RetroAchievements media in the snapshot is `ra-media/<path>`; draw a placeholder. */
  const raMedia = <T>(value: T): T =>
    JSON.parse(JSON.stringify(value), (_key, v: unknown) =>
      typeof v === 'string' && v.startsWith('ra-media/')
        ? placeholder(v.split('/').pop()!, 'badge')
        : v
    ) as T;
  const fetched = <T>(data: T) => ({
    data: raMedia(data),
    stale: false,
    fetchedAt: new Date().toISOString().slice(0, 19)
  });
  const raConfigured = () => {
    if (options.ra === false) {
      fail(
        'notConfigured',
        'set your RetroAchievements web API key as the Forma setting ra.apiKey'
      );
    }
  };

  const settingKey = (key: string, scope: unknown): string => {
    if (scope === 'system') {
      if (!permissions.has('settings.system')) {
        fail('permissionDenied', 'theme `mock` needs the `settings.system` permission');
      }
      return key;
    }
    return `theme.mock.${key}`;
  };

  // The user's collections, by name: one to start with, as a box with EmulationStation's.
  const collections = new Map<string, number[]>([
    [
      'Couch co-op',
      [...games.values()]
        .filter((g) => !g.hidden)
        .slice(0, 2)
        .map((g) => g.id)
    ]
  ]);
  const collection = (name: unknown): string =>
    [...collections.keys()].find((n) => n.toLowerCase() === String(name).trim().toLowerCase()) ??
    fail('notFound', `no collection called ${String(name)}`);
  const slug = (name: string) =>
    name
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, '-')
      .replace(/^-|-$/g, '') || 'collection';
  const sortedCollections = () =>
    [...collections.keys()].sort((a, b) => a.toLowerCase().localeCompare(b.toLowerCase()));
  const collectionsChanged = (system?: string) => {
    emit('views:changed', null);
    if (system) emit('library:changed', { systems: [system] } satisfies LibraryChanged);
  };
  /** The `collections` view, from the collections there are now. */
  const browseCollections = (path: string[]): Browse => {
    const names = sortedCollections();
    const inIt = (name: string) =>
      (collections.get(name) ?? [])
        .map((id) => games.get(id))
        .filter((g): g is Game => g !== undefined && !g.hidden)
        .sort((a, b) => a.name.localeCompare(b.name));
    if (path.length === 0) {
      return {
        view: 'collections',
        path,
        trail: [],
        listing: names.length
          ? {
              kind: 'branches',
              items: names.map((n) => ({ id: slug(n), name: n, gameCount: inIt(n).length }))
            }
          : { kind: 'games', items: [], total: 0 }
      };
    }
    const name =
      names.find((n) => slug(n) === path[0]) ??
      fail('invalid', 'no such path in view `collections`');
    const items = inIt(name);
    return {
      view: 'collections',
      path,
      trail: [{ key: path[0]!, label: name }],
      listing: { kind: 'games', items, total: items.length }
    };
  };

  const commands: Record<string, (args: Record<string, unknown>) => unknown> = {
    sdk_api_version: () => snapshot.apiVersion,
    magazines_list: (): Magazine[] =>
      magazines.map((m) => ({ ...m, page: reading.get(m.id) ?? null })),
    magazines_pages: ({ id }) =>
      magazines.some((m) => m.id === id)
        ? MAGAZINE_PAGES
        : fail('invalid', `no magazine \`${String(id)}\``),
    magazines_set_page: ({ id, page }) => {
      reading.set(String(id), Number(page));
      return null;
    },
    magazines_open: ({ id }) => {
      emit('magazines:open', { id: (id as string | null) ?? null });
      return null;
    },
    collections_list: (): Collection[] =>
      sortedCollections().map((name) => ({
        name,
        games: (collections.get(name) ?? []).filter((id) => games.has(id)).length
      })),
    collections_of: ({ gameId }) =>
      sortedCollections().filter((n) => collections.get(n)?.includes(gameId as number)),
    collections_create: ({ name }) => {
      const trimmed = String(name).trim();
      if (
        !trimmed ||
        trimmed.length > 64 ||
        /[/\\:*?"<>|]/.test(trimmed) ||
        trimmed.startsWith('.')
      ) {
        fail('invalid', `\`${trimmed}\` cannot be a collection's name`);
      }
      if ([...collections.keys()].some((n) => n.toLowerCase() === trimmed.toLowerCase())) {
        fail('invalid', `there is already a collection called ${trimmed}`);
      }
      collections.set(trimmed, []);
      collectionsChanged();
      return trimmed;
    },
    collections_delete: ({ name }) => {
      collections.delete(collection(name));
      collectionsChanged();
      return null;
    },
    collections_set: ({ name, gameId, member }) => {
      const key = collection(name);
      const game =
        games.get(gameId as number) ?? fail('notFound', `no game with id ${String(gameId)}`);
      const ids = (collections.get(key) ?? []).filter((id) => id !== game.id);
      collections.set(key, member ? [...ids, game.id] : ids);
      collectionsChanged(game.system);
      return null;
    },
    theme_ready: () => null,
    // In the order the user chose, as Forma lists them (`SystemsOrder`).
    library_systems: () => orderSystems(snapshot.systems, settings.get('library.systemsOrder')),
    library_game: ({ id }) => {
      const game = games.get(id as number);
      return game ? present(game) : null;
    },
    library_search: ({ query, limit }) => {
      const words = fold(String(query)).split(/\s+/).filter(Boolean);
      if (words.length === 0) return [];
      return [...games.values()]
        .filter((g) => !g.hidden)
        .filter((g) => {
          const text = fold([g.name, g.description, g.developer, g.publisher].join(' '));
          const tokens = text.split(/[^\p{L}\p{N}]+/u);
          return words.every((w) => tokens.some((t) => t.startsWith(w)));
        })
        .slice(0, (limit as number | undefined) ?? 50)
        .map(present);
    },
    library_set_favorite: ({ id, favorite }) => {
      const game = games.get(id as number) ?? fail('notFound', `no game with id ${String(id)}`);
      game.favorite = Boolean(favorite);
      emit('library:changed', { systems: [game.system] } satisfies LibraryChanged);
      return null;
    },
    nav_views: () => snapshot.views,
    nav_browse: ({ view, path, page }) => {
      if (!snapshot.views.some((v) => v.id === view))
        fail('notFound', `no view \`${String(view)}\``);
      if (view === 'collections') {
        return paginate(
          browseCollections((path as string[] | undefined) ?? []),
          page as { offset: number; limit: number } | undefined,
          present
        );
      }
      const key = JSON.stringify([view, ...((path as string[] | undefined) ?? [])]);
      const found =
        snapshot.browse[key] ?? fail('invalid', `no such path in view \`${String(view)}\``);
      return paginate(found, page as { offset: number; limit: number } | undefined, present);
    },
    nav_default_view: (): DefaultView => ({ id: defaultView ?? 'systems', notes: [] }),
    nav_set_default_view: ({ id }) => {
      if (id !== null && id !== undefined && !snapshot.views.some((v) => v.id === id)) {
        fail('notFound', `no view ${JSON.stringify(id)}`);
      }
      defaultView = (id as string | null) ?? null;
      return null;
    },
    shell_set_context: ({ context }) => {
      shellContext = context ?? null;
      return null;
    },
    // Forma's menu, as the mock plays it: a test can pick a view or change a setting as the
    // user would, and the theme hears of it.
    shell_open_view: ({ view }) => {
      emit('nav:open', { view });
      return null;
    },
    shell_info: () => ({ context: shellContext }),
    shell_set_theme_setting: ({ key, value }) => {
      settings.set(settingKey(String(key), 'theme'), value);
      emit('settings:changed', { scope: 'theme', key, value });
      return null;
    },
    settings_get: ({ key, scope }) => settings.get(settingKey(String(key), scope)) ?? null,
    settings_set: ({ key, value, scope }) => {
      const k = settingKey(String(key), scope);
      if (value === null || value === undefined) settings.delete(k);
      else settings.set(k, structuredClone(value));
      return null;
    },
    themes_list: (): ThemeInfo[] => [
      {
        id: 'mock',
        name: 'Mock',
        version: null,
        origin: 'user',
        author: null,
        description: null,
        permissions: [...permissions],
        permissionDescriptions: [...permissions],
        removable: false,
        update: null,
        current: true,
        unavailable: null,
        logo: null
      },
      ...extraThemes.map((t) => structuredClone(t))
    ],
    themes_select: ({ id }) =>
      id === 'mock' || extraThemes.some((t) => t.id === id)
        ? null
        : fail('notFound', `theme \`${String(id)}\` is not available`),
    themes_catalogue: (): Fetched<ThemeCatalogue> => ({
      data: { themes: structuredClone(catalogue), skipped: [] },
      stale: false,
      fetchedAt: new Date().toISOString().slice(0, 19)
    }),
    themes_install: ({ id }) => {
      if (!permissions.has('themes.manage')) {
        fail('permissionDenied', 'theme `mock` needs the `themes.manage` permission');
      }
      const entry =
        catalogue.find((c) => c.id === id) ??
        fail('notFound', `no theme \`${String(id)}\` in the catalogue`);
      entry.installed = entry.version;
      entry.update = false;
      const installed = extraThemes.find((t) => t.id === id);
      if (installed) {
        installed.version = entry.version;
        installed.update = null;
      } else {
        extraThemes.push({
          id: entry.id,
          name: entry.name,
          version: entry.version,
          origin: 'user',
          author: entry.author,
          description: entry.description,
          permissions: [...entry.permissions],
          permissionDescriptions: [...entry.permissionDescriptions],
          removable: true,
          update: null,
          current: false,
          unavailable: null,
          logo: null
        });
      }
      return null;
    },
    themes_remove: ({ id }) => {
      if (!permissions.has('themes.manage')) {
        fail('permissionDenied', 'theme `mock` needs the `themes.manage` permission');
      }
      if (id === 'mock') fail('invalid', 'theme `mock` is in use: switch to another one first');
      const at = extraThemes.findIndex((t) => t.id === id);
      if (at < 0) fail('notFound', `no installed theme \`${String(id)}\``);
      extraThemes.splice(at, 1);
      const listed = catalogue.find((c) => c.id === id);
      if (listed) Object.assign(listed, { installed: null, update: false });
      return null;
    },
    input_controllers: () => [],
    // One pad, on a cable, online: what the corner shows in a browser.
    status_get: () => ({
      controllers: [{ player: 1, name: 'Xbox 360 Controller', kind: 'xbox' }],
      network: { kind: 'ethernet', internet: true }
    }),
    ra_matches: () => ({
      running: false,
      systems: [
        { system: 'nes', games: 4, hashed: 4, matched: 3 },
        { system: 'snes', games: 2, hashed: 2, matched: 1 },
        { system: 'psx', games: 1, hashed: 0, matched: 0 }
      ]
    }),
    ra_user: () => {
      raConfigured();
      return fetched(snapshot.ra.user);
    },
    ra_game: ({ id }) => {
      raConfigured();
      const game = snapshot.ra.games[String(id)];
      if (!game) fail('notFound', `no RetroAchievements id is known for game ${String(id)} yet`);
      return fetched(game);
    },
    netplay_lobby: ({ filter }) => fetched(rooms(snapshot.lobby, filter as RoomFilter | undefined)),
    // A host next door: the lobby's first room, found on the local network.
    netplay_lan: ({ filter }) =>
      rooms(
        snapshot.lobby.slice(0, 1).map((r) => ({
          ...r,
          id: -1,
          lan: true,
          host: '192.168.1.50',
          join: { host: '192.168.1.50', port: r.port ?? 55435, session: null }
        })),
        filter as RoomFilter | undefined
      ),
    updates_check: () => {
      updatesAllowed();
      return { ...updates, available: updates.latest !== updates.current };
    },
    updates_install: async () => {
      updatesAllowed();
      if (updates.latest === updates.current) fail('unsupported', 'Batocera is up to date');
      for (const percent of [0, 50, 100]) {
        emit('updates:progress', { message: 'Downloading', percent });
        await new Promise((r) => setTimeout(r, 10));
      }
      emit('updates:progress', { message: 'Extracting files', percent: null });
      updates.current = updates.latest;
      return null;
    },
    bluetooth_status: () => {
      bluetoothAllowed();
      return {
        enabled: bluetooth.enabled,
        devices: bluetooth.enabled ? structuredClone(bluetooth.devices) : []
      };
    },
    bluetooth_set_enabled: ({ enabled }) => {
      bluetoothAllowed();
      bluetooth.enabled = Boolean(enabled);
      return null;
    },
    bluetooth_pair: async () => {
      bluetoothAllowed();
      if (!bluetooth.enabled) fail('unsupported', 'Bluetooth is off');
      emit('bluetooth:pairing', { message: 'Discovering…' });
      await new Promise((r) => setTimeout(r, 50));
      const found = {
        address: '9C:DE:B3:05:06:07',
        name: 'Wireless Controller',
        controller: true,
        connected: true
      };
      emit('bluetooth:pairing', { message: `Pairing ${found.name}` });
      if (bluetooth.devices.some((d) => d.address === found.address)) return [];
      bluetooth.devices.push(found);
      return [structuredClone(found)];
    },
    bluetooth_connect: ({ address }) => bluetoothDevice(address, (d) => (d.connected = true)),
    bluetooth_disconnect: ({ address }) => bluetoothDevice(address, (d) => (d.connected = false)),
    bluetooth_forget: ({ address }) => {
      bluetoothDevice(address, () => {});
      bluetooth.devices = bluetooth.devices.filter((d) => d.address !== address);
      return null;
    },
    network_status: () => {
      networkAllowed();
      return structuredClone(network.status);
    },
    network_wifi_scan: () => {
      networkAllowed();
      if (!network.status.wifi?.enabled) return [];
      return network.wifi.map((n) => ({
        ...n,
        saved: n.ssid === network.status.wifi?.saved,
        connected: n.ssid === network.status.wifi?.connected
      }));
    },
    network_wifi_join: ({ ssid, passphrase }) => {
      networkAllowed();
      const target = network.wifi.find((n) => n.ssid === ssid);
      if (target?.security === 'enterprise') {
        fail('unsupported', `${String(ssid)} needs 802.1X, which Batocera cannot set up`);
      }
      const key = typeof passphrase === 'string' ? passphrase : '';
      if (target?.security !== 'open' && key.length < 8) {
        fail('invalid', 'a Wi-Fi password is 8 to 63 characters');
      }
      // The mock's one wrong password, for trying a theme's error handling.
      if (key === 'wrong-password') {
        fail('network', `${String(ssid)} refused the connection: check the password`);
      }
      const wifi = network.status.wifi ?? fail('unsupported', 'this box has no Wi-Fi');
      wifi.enabled = true;
      wifi.saved = String(ssid);
      // As on Batocera: with a cable in, Ethernet stays in use.
      if (network.status.ethernet?.connected) return 'saved';
      wifi.connected = String(ssid);
      wifi.ipv4 = { address: '192.168.1.120', netmask: '255.255.255.0', gateway: '192.168.1.254' };
      return 'connected';
    },
    network_wifi_set_enabled: ({ enabled }) => {
      networkAllowed();
      const wifi = network.status.wifi ?? fail('unsupported', 'this box has no Wi-Fi');
      wifi.enabled = Boolean(enabled);
      if (!wifi.enabled) {
        wifi.connected = null;
        wifi.ipv4 = null;
      }
      return null;
    },
    network_ethernet_configure: ({ config }) => {
      networkAllowed();
      const ethernet =
        network.status.ethernet ?? fail('unsupported', 'this box has no wired network interface');
      const c = config as EthernetConfig;
      const ipv4 = /^(\d{1,3})(\.\d{1,3}){3}$/;
      if (c.method === 'manual' && (!ipv4.test(c.address) || !ipv4.test(c.netmask))) {
        fail('invalid', `the address ${JSON.stringify(c.address)} is not an IPv4 address`);
      }
      ethernet.config = structuredClone(c);
      if (c.method === 'manual') {
        ethernet.ipv4 = { address: c.address, netmask: c.netmask, gateway: c.gateway };
        ethernet.nameservers = [...c.nameservers];
      }
      return null;
    },
    batocera_settings: ({ prefix }) => {
      batoceraAllowed();
      const p = typeof prefix === 'string' ? prefix : '';
      return [...batocera.values()].filter((s) => s.key.startsWith(p)).map((s) => ({ ...s }));
    },
    store_list: () => {
      storeAllowed();
      return structuredClone(store);
    },
    store_refresh: () => storeWork(() => {}),
    store_install: ({ name }) =>
      storeWork(async () => {
        const p = storePackage(name);
        for (const [stage, percent] of [
          ['download', 0],
          ['download', 50],
          ['download', 100],
          ['install', 50]
        ] as const) {
          emit('store:progress', { name: p.name, stage, percent });
          await new Promise((r) => setTimeout(r, playMs / 10));
        }
        p.installed = true;
        p.update = false;
      }),
    store_remove: ({ name }) =>
      storeWork(() => {
        const p = storePackage(name);
        if (!p.installed) fail('network', `the content downloader could not remove: not installed`);
        p.installed = false;
        p.update = false;
      }),
    store_update: () =>
      storeWork(() => {
        for (const p of store) p.update = false;
      }),
    system_info: () => {
      systemAllowed();
      return structuredClone(snapshot.system.info);
    },
    system_settings: () => {
      systemAllowed();
      return structuredClone(systemSettings);
    },
    system_settings_set: ({ key, value }) => {
      systemAllowed();
      const s =
        systemSettings.find((x) => x.key === key) ??
        fail('invalid', `\`${String(key)}\` is not a system setting`);
      const v = typeof value === 'string' ? value.trim() : '';
      if (v === '' && s.key === 'storage') fail('invalid', 'choose a storage device');
      const ok =
        v === '' ||
        (s.kind === 'text'
          ? /^[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?$/.test(v)
          : s.kind === 'number'
            ? /^\d+$/.test(v) && Number(v) >= (s.min ?? 0) && Number(v) <= (s.max ?? 100)
            : s.choices.some((c) => c.value === v));
      if (!ok) fail('invalid', `\`${v}\` is not allowed for \`${s.key}\``);
      s.value = v === '' ? null : v;
      return null;
    },
    options_get: ({ scope }) => {
      optionsAllowed();
      return optionsPage(scope as OptionsScope);
    },
    options_set: ({ scope, key, value }) => {
      optionsAllowed();
      const s = scope as OptionsScope;
      const item =
        optionsPage(s).options.find((o) => o.key === key) ??
        fail('invalid', `\`${String(key)}\` is not an option here`);
      const prefix = levels(s)[0]!.prefix;
      const v = typeof value === 'string' ? value.trim() : '';
      if (v === '') conf.delete(`${prefix}.${item.key}`);
      else {
        const n = Number(v);
        const ok =
          item.kind === 'text'
            ? !/[\r\n]/.test(v)
            : item.kind === 'number'
              ? Number.isFinite(n) && n >= (item.min ?? -Infinity) && n <= (item.max ?? Infinity)
              : item.choices.some((c) => c.value === v);
        if (!ok) fail('invalid', `\`${item.key}\`: \`${v}\` is not allowed`);
        conf.set(`${prefix}.${item.key}`, v);
      }
      // A core belongs to its emulator.
      if (item.key === 'emulator' && v !== item.value) conf.delete(`${prefix}.core`);
      return null;
    },
    batocera_set: ({ key, value }) => {
      batoceraAllowed();
      const setting =
        batocera.get(String(key)) ??
        fail('invalid', `\`${String(key)}\` is not a setting Forma can change`);
      const v = typeof value === 'string' ? value.trim() : '';
      if (setting.kind === 'secret') fail('invalid', `\`${setting.key}\` is set by logging in`);
      if (setting.kind === 'bool' && v !== '0' && v !== '1') fail('invalid', 'a switch is 0 or 1');
      if (setting.kind === 'choice' && v && !setting.choices.includes(v)) {
        fail('invalid', `\`${setting.key}\` is one of: ${setting.choices.join(', ')}`);
      }
      setting.value = v || null;
      setting.set = Boolean(v);
      return null;
    },
    ra_login: ({ username, password }) => {
      batoceraAllowed();
      const user = typeof username === 'string' ? username.trim() : '';
      const secret = typeof password === 'string' ? password : '';
      // The mock's one wrong password, for trying a theme's error handling.
      if (!user || !secret || secret === 'wrong-password') {
        fail('invalid', 'RetroAchievements refused the login: check the username and password');
      }
      const put = (key: string, value: string) => {
        const s = batocera.get(key);
        if (s) Object.assign(s, { value: s.kind === 'secret' ? null : value, set: true });
      };
      put('global.retroachievements', '1');
      put('global.retroachievements.username', user);
      put('global.retroachievements.password', secret);
      put('global.retroachievements.token', 'mock-token');
      return user;
    },
    ra_logout: () => {
      batoceraAllowed();
      for (const key of ['global.retroachievements.password', 'global.retroachievements.token']) {
        const s = batocera.get(key);
        if (s) Object.assign(s, { value: null, set: false });
      }
      const on = batocera.get('global.retroachievements');
      if (on) Object.assign(on, { value: '0', set: true });
      return null;
    },
    music_sources: () => musicSources(),
    music_status: () => structuredClone(music),
    music_play: ({ source, options }) => {
      const found =
        musicSources().find((s) => s.id === source) ??
        fail('invalid', `nothing to play called \`${String(source)}\``);
      const radio = found.kind === 'radio';
      return playerSet({
        state: 'playing',
        source: found,
        title: radio ? 'Live' : trackTitle(1),
        artist: radio ? found.name : null,
        position: radio ? null : 0,
        duration: radio ? null : 180,
        track: radio ? null : 1,
        tracks: radio ? null : found.tracks,
        shuffle: Boolean((options as { shuffle?: boolean } | undefined)?.shuffle)
      });
    },
    music_toggle: () =>
      music.state === 'stopped'
        ? structuredClone(music)
        : playerSet({ state: music.state === 'playing' ? 'paused' : 'playing' }),
    music_next: () => {
      if (music.track === null || music.tracks === null) return structuredClone(music);
      const track = Math.min(music.tracks, music.track + 1);
      return playerSet({ track, title: trackTitle(track) });
    },
    music_previous: () => {
      if (music.track === null) return structuredClone(music);
      const track = Math.max(1, music.track - 1);
      return playerSet({ track, title: trackTitle(track) });
    },
    music_stop: () =>
      playerSet({
        state: 'stopped',
        source: null,
        title: null,
        artist: null,
        position: null,
        duration: null,
        track: null,
        tracks: null
      }),
    music_set_volume: ({ volume }) =>
      playerSet({ volume: Math.max(0, Math.min(100, Math.round(Number(volume) || 0))) }),
    music_radios: () => structuredClone(radios),
    music_add_radio: ({ name, url }) => {
      musicManage();
      const u = typeof url === 'string' ? url.trim() : '';
      const n = typeof name === 'string' ? name.trim() : '';
      if (!/^https?:\/\/\S+$/.test(u)) fail('invalid', `${JSON.stringify(u)} is not a web address`);
      if (!n) fail('invalid', 'a radio needs a name');
      const at = radios.findIndex((r) => r.url === u);
      if (at >= 0) radios.splice(at, 1);
      radios.push({ name: n, url: u });
      return null;
    },
    music_remove_radio: ({ url }) => {
      musicManage();
      const at = radios.findIndex((r) => r.url === url);
      if (at < 0) fail('invalid', `no radio at ${String(url)}`);
      radios.splice(at, 1);
      return null;
    },
    system_quit: () => power(),
    system_power: () => power(),
    launch_game: ({ id }) => {
      if (playing) fail('busy', 'a game is already running');
      const game = games.get(id as number) ?? fail('launch', `no game with id ${String(id)}`);
      playing = true;
      emit('game:start', {
        type: 'game:start',
        gameId: game.id,
        system: game.system,
        name: game.name
      } satisfies GameStart);
      setTimeout(() => {
        playing = false;
        game.playCount += 1;
        game.lastPlayed = new Date().toISOString().slice(0, 19);
        game.gameTime += Math.round(playMs / 1000);
        emit('game:end', {
          type: 'game:end',
          gameId: game.id,
          seconds: Math.round(playMs / 1000),
          exitCode: 0,
          error: null
        } satisfies GameEnd);
        emit('library:changed', { systems: [game.system] } satisfies LibraryChanged);
        // A game RetroAchievements knows: the session earned what was still locked.
        const ra = snapshot.ra.games[String(game.id)];
        const locked = ra?.achievements.filter((x) => x.earnedAt === null) ?? [];
        if (ra && locked.length) {
          const now = new Date().toISOString().slice(0, 19).replace('T', ' ');
          const unlocked = locked.map((x) => ({ ...x, earnedAt: now }));
          emit('ra:unlocked', {
            gameId: game.id,
            game: {
              ...ra,
              earned: ra.earned + unlocked.length,
              completion: (ra.earned + unlocked.length) / Math.max(1, ra.achievementCount)
            },
            unlocked,
            points: unlocked.reduce((n, x) => n + x.points, 0)
          } satisfies RaSession);
        }
      }, playMs);
      return null;
    }
  };

  /** As Forma filters rooms; every ping is 30 ms. */
  function rooms(all: NetplayRoom[], filter: RoomFilter = {}): NetplayRoom[] {
    return all
      .filter(
        (r) =>
          (!filter.owned || r.localGameId !== null) &&
          (!filter.joinable || (r.core !== null && r.join !== null)) &&
          (!filter.open || !r.hasPassword) &&
          (!filter.coreName || r.coreName.toLowerCase() === filter.coreName.toLowerCase())
      )
      .map((r) => (filter.maxPingMs === undefined ? r : { ...r, pingMs: 30 }))
      .filter((r) => filter.maxPingMs === undefined || (r.pingMs ?? Infinity) <= filter.maxPingMs);
  }

  function musicManage(): void {
    if (!permissions.has('music.manage')) {
      fail('permissionDenied', 'theme `mock` needs the `music.manage` permission');
    }
  }

  function batoceraAllowed(): void {
    if (!permissions.has('settings.batocera')) {
      fail('permissionDenied', 'theme `mock` needs the `settings.batocera` permission');
    }
  }

  function storeAllowed(): void {
    if (!permissions.has('store.manage')) {
      fail('permissionDenied', 'theme `mock` needs the `store.manage` permission');
    }
  }

  function systemAllowed(): void {
    if (!permissions.has('system.settings')) {
      fail('permissionDenied', 'theme `mock` needs the `system.settings` permission');
    }
  }

  function optionsAllowed(): void {
    if (!permissions.has('settings.emulators')) {
      fail('permissionDenied', 'theme `mock` needs the `settings.emulators` permission');
    }
  }

  function updatesAllowed(): void {
    if (!permissions.has('system.update')) {
      fail('permissionDenied', 'theme `mock` needs the `system.update` permission');
    }
  }

  function bluetoothAllowed(): void {
    if (!permissions.has('system.controllers')) {
      fail('permissionDenied', 'theme `mock` needs the `system.controllers` permission');
    }
  }

  function bluetoothDevice(address: unknown, change: (d: BluetoothDevice) => void): null {
    bluetoothAllowed();
    const d =
      bluetooth.devices.find((x) => x.address === address) ??
      fail('invalid', `no paired device \`${String(address)}\``);
    change(d);
    return null;
  }

  function networkAllowed(): void {
    if (!permissions.has('system.network')) {
      fail('permissionDenied', 'theme `mock` needs the `system.network` permission');
    }
  }

  function power(): never {
    if (!permissions.has('system.power')) {
      fail('permissionDenied', 'theme `mock` needs the `system.power` permission');
    }
    fail('unsupported', 'the mock cannot quit, restart or shut down');
  }

  return {
    kind: 'mock',
    invoke<T>(command: string, args: Record<string, unknown> = {}): Promise<T> {
      const run = commands[command];
      if (!run) return Promise.reject(new FormaError('notFound', `unknown command ${command}`));
      try {
        return Promise.resolve(run(args) as T);
      } catch (error) {
        return Promise.reject(FormaError.from(error));
      }
    },
    listen<T>(event: string, handler: (payload: T) => void): Unsubscribe {
      const set = listeners.get(event) ?? new Set<Handler>();
      listeners.set(event, set);
      set.add(handler as Handler);
      return () => set.delete(handler as Handler);
    },
    mediaUrl
  };
}

function paginate(
  browse: Browse,
  page: { offset: number; limit: number } | undefined,
  present: (g: Game) => Game
): Browse {
  const offset = page?.offset ?? 0;
  const limit = page?.limit ?? 200;
  const listing = browse.listing;
  switch (listing.kind) {
    case 'branches':
      return browse;
    case 'groups':
      return {
        ...browse,
        listing: { ...listing, items: listing.items.slice(offset, offset + limit) }
      };
    case 'games':
      return {
        ...browse,
        listing: { ...listing, items: listing.items.slice(offset, offset + limit).map(present) }
      };
  }
}

function escapeXml(s: string): string {
  return s.replace(
    /[<>&"]/g,
    (c) => ({ '<': '&lt;', '>': '&gt;', '&': '&amp;', '"': '&quot;' })[c]!
  );
}

/** Forma's systems order (`SystemsOrder`): by name unless the setting says maker or year. */
function orderSystems(systems: SystemSummary[], order: unknown): SystemSummary[] {
  const name = (s: SystemSummary) => s.fullname.toLowerCase();
  const year = (s: SystemSummary) => s.releaseYear ?? Number.MAX_SAFE_INTEGER;
  const maker = (s: SystemSummary) => s.manufacturer?.trim().toLowerCase() || null;
  const byName = (a: SystemSummary, b: SystemSummary) => name(a).localeCompare(name(b));
  return [...systems].sort((a, b) => {
    if (order === 'year') return year(a) - year(b) || byName(a, b);
    if (order === 'maker') {
      const [ma, mb] = [maker(a), maker(b)];
      if (ma !== mb) return ma === null ? 1 : mb === null ? -1 : ma.localeCompare(mb);
      return year(a) - year(b) || byName(a, b);
    }
    return byName(a, b);
  });
}
